class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        dp_even = {}  # Maps alternating sum -> max product for even-length subsequences
        dp_odd = {}   # Maps alternating sum -> max product for odd-length subsequences

        for x in nums:
            new_even = dp_even.copy()
            new_odd = dp_odd.copy()

            # Start a new subsequence with just x (length 1, odd index 0 -> add)
            if x <= limit:
                if x > new_odd.get(x, -1):
                    new_odd[x] = x

            # Extend even-length subsequences -> become odd-length
            # Next index is even, so we ADD x to the alternating sum
            for s, p in dp_even.items():
                ns = s + x
                np = p * x
                if np <= limit:
                    if np > new_odd.get(ns, -1):
                        new_odd[ns] = np

            # Extend odd-length subsequences -> become even-length
            # Next index is odd, so we SUBTRACT x from the alternating sum
            for s, p in dp_odd.items():
                ns = s - x
                np = p * x
                if np <= limit:
                    if np > new_even.get(ns, -1):
                        new_even[ns] = np

            dp_even = new_even
            dp_odd = new_odd

        return max(dp_even.get(k, -1), dp_odd.get(k, -1))

