class Solution:
    def minimumCost(self, nums: List[int], cost: List[int], k: int) -> int:
        n = len(nums)
        P = [0] * (n + 1)
        C = [0] * (n + 1)
        for i in range(n):
            P[i + 1] = P[i] + nums[i]
            C[i + 1] = C[i] + cost[i]

        INF = float('inf')
        prev_dp = [INF] * (n + 1)
        prev_dp[0] = 0

        ans = INF

        for j in range(1, n + 1):
            curr_dp = [INF] * (n + 1)
            hull = deque()

            # Add line for l = j-1 (first valid partition point)
            if prev_dp[j - 1] < INF:
                hull.append((-C[j - 1], prev_dp[j - 1]))

            for i in range(j, n + 1):
                x = P[i] + k * j

                # Query: find line minimizing m*x + b
                # Slopes are non-increasing, query x is increasing
                while len(hull) >= 2:
                    m1, b1 = hull[0]
                    m2, b2 = hull[1]
                    if (m1 - m2) * x > b2 - b1:
                        hull.popleft()
                    else:
                        break

                if hull:
                    m, b = hull[0]
                    val = m * x + b
                    if val < INF:
                        curr_dp[i] = (P[i] + k * j) * C[i] + val

                # Add line for l = i (for future queries in this j)
                if prev_dp[i] < INF:
                    new_m = -C[i]
                    new_b = prev_dp[i]

                    # Handle equal slopes (keep line with smaller intercept)
                    while hull and hull[-1][0] == new_m:
                        if hull[-1][1] <= new_b:
                            new_m = None
                            break
                        else:
                            hull.pop()

                    if new_m is not None:
                        # Remove lines from back made redundant by new line
                        while len(hull) >= 2:
                            m1, b1 = hull[-2]
                            m2, b2 = hull[-1]
                            # Line 2 is redundant if intersection(1,3) <= intersection(1,2)
                            if (new_b - b2) * (m1 - m2) <= (b2 - b1) * (m2 - new_m):
                                hull.pop()
                            else:
                                break
                        hull.append((new_m, new_b))

            if curr_dp[n] < ans:
                ans = curr_dp[n]
            prev_dp = curr_dp

        return ans

class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        def sum_depths(n: int) -> int:
            if n <= 0:
                return 0
            total = 0
            p = 1
            k = 0
            while p <= n:
                next_p = p * 4
                count = min(n, next_p - 1) - p + 1
                total += count * (k + 1)
                p = next_p
                k += 1
            return total

        result = 0
        for l, r in queries:
            total_depth = sum_depths(r) - sum_depths(l - 1)
            result += (total_depth + 1) // 2
        return result

class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        if n < k:
            return [0] * n
        if n == k:
            return [0] * n

        trie = [{}]
        count = [0]
        depth = [0]

        for w in words:
            curr = 0
            for char in w:
                if char not in trie[curr]:
                    trie[curr][char] = len(trie)
                    trie.append({})
                    count.append(0)
                    depth.append(len(trie) - 1)
                curr = trie[curr][char]
                count[curr] += 1

        L_gt_k = 0
        for i in range(1, len(count)):
            if count[i] > k:
                L_gt_k = max(L_gt_k, depth[i])

        best = [-1] * len(trie)
        stack = [0]
        order = []
        while stack:
            u = stack.pop()
            order.append(u)
            for v in trie[u].values():
                stack.append(v)

        for u in reversed(order):
            if count[u] == k:
                best[u] = max(best[u], depth[u])
            for v in trie[u].values():
                best[u] = max(best[u], best[v])

        max1 = [-1] * len(trie)
        max2 = [-1] * len(trie)
        for u in range(len(trie)):
            for v in trie[u].values():
                val = best[v]
                if val > max1[u]:
                    max2[u] = max1[u]
                    max1[u] = val
                elif val > max2[u]:
                    max2[u] = val

        ans = [0] * n
        for i, w in enumerate(words):
            curr = 0
            res = L_gt_k
            for char in w:
                if char not in trie[curr]:
                    break
                v = trie[curr][char]
                if best[v] == max1[curr]:
                    sib = max2[curr]
                else:
                    sib = max1[curr]
                res = max(res, sib)
                curr = v
            res = max(res, max1[curr])
            ans[i] = res

        return ans

