import sys

def solve():
    # Fast I/O
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        N = int(next(iterator))
        K = int(next(iterator))
    except StopIteration:
        return

    num_vertices = N * K

    # If K=1, every vertex is a path of length 1. Always possible.
    if K == 1:
        print("Yes")
        return

    adj = [[] for _ in range(num_vertices + 1)]

    # Reading edges
    for _ in range(num_vertices - 1):
        try:
            u = int(next(iterator))
            v = int(next(iterator))
            adj[u].append(v)
            adj[v].append(u)
        except StopIteration:
            break

    # Iterative DFS to determine processing order (post-order)
    # We root the tree at vertex 1
    parent = [0] * (num_vertices + 1)
    order = []
    stack = [1]
    visited = [False] * (num_vertices + 1)
    visited[1] = True

    while stack:
        u = stack.pop()
        order.append(u)
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                stack.append(v)

    # L[u] stores the length of the open path ending at u in its subtree.
    # If L[u] == 0, the subtree is fully decomposed into closed paths.
    L = [0] * (num_vertices + 1)
    possible = True

    # Process in reverse order (leaves to root)
    for u in reversed(order):
        if not possible:
            break

        cnt = 0
        first_len = 0
        second_len = 0

        # Identify children and their L values
        for v in adj[u]:
            if v == parent[u]:
                continue
            val = L[v]
            if val > 0:
                cnt += 1
                if cnt == 1:
                    first_len = val
                elif cnt == 2:
                    second_len = val
                else:
                    # More than 2 open paths meeting at u is impossible
                    possible = False
                    L[u] = -1
                    break

        if not possible:
            continue

        if cnt == 0:
            # No paths coming from children, start new path of length 1
            L[u] = 1
        elif cnt == 1:
            # Connect to one child
            new_len = first_len + 1
            if new_len == K:
                L[u] = 0
            elif new_len < K:
                L[u] = new_len
            else:
                possible = False
                L[u] = -1
        elif cnt == 2:
            # Connect to two children, merge paths
            new_len = first_len + 1 + second_len
            if new_len == K:
                L[u] = 0
            else:
                possible = False
                L[u] = -1

    if possible and L[1] == 0:
        print("Yes")
    else:
        print("No")

