class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        L = n + m - 1
        word = [None] * L
        forced = [None] * L

        # Precompute forced characters from 'T' constraints
        for i in range(n):
            if str1[i] == 'T':
                for k in range(m):
                    pos = i + k
                    if forced[pos] is None:
                        forced[pos] = str2[k]
                    elif forced[pos] != str2[k]:
                        return ""

        # Track state for 'F' constraints
        is_active = [False] * n
        count_free = [0] * n
        for i in range(n):
            if str1[i] == 'F':
                is_active[i] = True
                count_free[i] = m

        for j in range(L):
            # Determine forbidden characters from critical 'F' constraints
            forbidden = [False] * 26
            start_i = max(0, j - m + 1)
            end_i = min(j, n - 1)
            for i in range(start_i, end_i + 1):
                if is_active[i] and count_free[i] == 1:
                    forbidden[ord(str2[j - i]) - ord('a')] = True

            # Pick the lexicographically smallest valid character
            if forced[j] is not None:
                c = forced[j]
                if forbidden[ord(c) - ord('a')]:
                    return ""
            else:
                c = None
                for char_code in range(ord('a'), ord('z') + 1):
                    if not forbidden[char_code - ord('a')]:
                        c = chr(char_code)
                        break
                if c is None:
                    return ""

            word[j] = c

            # Update states for 'F' constraints
            for i in range(start_i, end_i + 1):
                if str1[i] == 'F':
                    count_free[i] -= 1
                    if c != str2[j - i]:
                        is_active[i] = False
                    # If window is fully filled and still matches str2, F constraint violated
                    if count_free[i] == 0 and is_active[i]:
                        return ""

        return "".join(word)

import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        N = int(next(iterator))
    except StopIteration:
        return

    W = [0] * (N + 1)
    for i in range(1, N + 1):
        W[i] = int(next(iterator))

    L = [0] * (N + 1)
    R = [0] * (N + 1)

    max_coord = 0
    for i in range(1, N + 1):
        l_val = int(next(iterator))
        r_val = int(next(iterator))
        L[i] = l_val
        R[i] = r_val
        if r_val > max_coord:
            max_coord = r_val

    size = max_coord + 5
    INF = float('inf')

    # min_left[x]: min weight of interval with R < x
    arr_left = [INF] * (size + 1)
    for i in range(1, N + 1):
        idx = R[i] + 1
        if idx < size:
            if W[i] < arr_left[idx]:
                arr_left[idx] = W[i]

    min_left = [INF] * (size + 1)
    current_min = INF
    for x in range(1, size + 1):
        if arr_left[x] < current_min:
            current_min = arr_left[x]
        min_left[x] = current_min

    # min_right[x]: min weight of interval with L > x
    arr_right = [INF] * (size + 1)
    for i in range(1, N + 1):
        idx = L[i] - 1
        if idx >= 0 and idx < size:
            if W[i] < arr_right[idx]:
                arr_right[idx] = W[i]

    min_right = [INF] * (size + 1)
    current_min = INF
    for x in range(size - 1, -1, -1):
        if arr_right[x] < current_min:
            current_min = arr_right[x]
        min_right[x] = current_min

    try:
        Q_val = next(iterator)
        Q = int(Q_val)
    except StopIteration:
        Q = 0

    results = []

    for _ in range(Q):
        try:
            s = int(next(iterator))
            t = int(next(iterator))
        except StopIteration:
            break

        # Check direct edge (intervals are disjoint)
        if R[s] < L[t] or R[t] < L[s]:
            results.append(str(W[s] + W[t]))
            continue

        # Intervals intersect, check for paths of length 2 and 3
        ans = INF

        # Common neighbor left: need interval with R < min(L[s], L[t])
        idx_common_left = min(L[s], L[t])
        if idx_common_left < size:
            val = min_left[idx_common_left]
            if val != INF:
                cand = W[s] + W[t] + val
                if cand < ans:
                    ans = cand

        # Common neighbor right: need interval with L > max(R[s], R[t])
        idx_common_right = max(R[s], R[t])
        if idx_common_right < size:
            val = min_right[idx_common_right]
            if val != INF:
                cand = W[s] + W[t] + val
                if cand < ans:
                    ans = cand

        # Left-Right path: u left of s (R[u] < L[s]), v right of t (L[v] > R[t])
        idx_u = L[s]
        idx_v = R[t]
        if idx_u < size and idx_v < size:
            val_u = min_left[idx_u]
            val_v = min_right[idx_v]
            if val_u != INF and val_v != INF:
                cand = W[s] + W[t] + val_u + val_v
                if cand < ans:
                    ans = cand

        # Right-Left path: u right of s (L[u] > R[s]), v left of t (R[v] < L[t])
        idx_u = R[s]
        idx_v = L[t]
        if idx_u < size and idx_v < size:
            val_u = min_right[idx_u]
            val_v = min_left[idx_v]
            if val_u != INF and val_v != INF:
                cand = W[s] + W[t] + val_u + val_v
                if cand < ans:
                    ans = cand

        if ans == INF:
            results.append("-1")
        else:
            results.append(str(ans))

    sys.stdout.write('\n'.join(results) + '\n')

