class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        def get_d(x, y):
            if y == 0:
                return x
            elif x == side:
                return side + y
            elif y == side:
                return 2 * side + (side - x)
            else:  # x == 0
                return 3 * side + (side - y)

        # Map each point to its perimeter coordinate
        coords = sorted([get_d(p[0], p[1]) for p in points])
        n = len(coords)
        circumference = 4 * side

        # Duplicate coordinates to handle circularity
        coords += [c + circumference for c in coords]

        def feasible(D):
            # Precompute the index of the next valid point for each point
            next_valid = [0] * n
            j = 0
            for i in range(n):
                while j < 2 * n and coords[j] - coords[i] < D:
                    j += 1
                next_valid[i] = j

            # Greedily check if we can pick k points starting from each index
            for i in range(n):
                curr = i
                count = 1
                for _ in range(k - 1):
                    curr = next_valid[curr]
                    # If we wrap around more than once, this starting point fails
                    if curr >= i + n:
                        break
                    count += 1
                if count == k:
                    return True
            return False

        # Binary search for the maximum possible minimum distance
        low, high = 1, circumference
        ans = 1
        while low <= high:
            mid = (low + high) // 2
            if feasible(mid):
                ans = mid
                low = mid + 1
            else:
                high = mid - 1
        return ans

