class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        # Directions: 0: DR, 1: UL, 2: DL, 3: UR
        dirs = [(1, 1), (-1, -1), (1, -1), (-1, 1)]
        # Valid clockwise 90-degree turns
        turns = [(0, 2), (2, 3), (3, 1), (1, 0)]

        # dp[d][i][j] stores the max length of a valid sequence ending at (i,j) in direction d
        dp = [[[0]*m for _ in range(n)] for _ in range(4)]
        # sl2[d][i][j] stores max length starting at (i,j) in direction d, expecting 2 next
        sl2 = [[[0]*m for _ in range(n)] for _ in range(4)]
        # sl0[d][i][j] stores max length starting at (i,j) in direction d, expecting 0 next
        sl0 = [[[0]*m for _ in range(n)] for _ in range(4)]

        # Compute dp tables
        for d in range(4):
            dr, dc = dirs[d]
            # Determine iteration order to ensure dependencies are computed first
            if d == 0: ri, ci = range(n), range(m)
            elif d == 1: ri, ci = range(n-1, -1, -1), range(m-1, -1, -1)
            elif d == 2: ri, ci = range(n), range(m-1, -1, -1)
            else: ri, ci = range(n-1, -1, -1), range(m)

            for i in ri:
                for j in ci:
                    if grid[i][j] == 1:
                        dp[d][i][j] = 1
                    else:
                        pi, pj = i - dr, j - dc
                        if 0 <= pi < n and 0 <= pj < m and dp[d][pi][pj] > 0:
                            prev_len = dp[d][pi][pj]
                            # Sequence: 1, 2, 0, 2, 0... Index 0 is 1, 1 is 2, 2 is 0...
                            expected = 2 if prev_len % 2 == 1 else 0
                            if grid[i][j] == expected:
                                dp[d][i][j] = prev_len + 1

        # Compute sl2 and sl0 tables (reverse direction DP)
        for d in range(4):
            dr, dc = dirs[d]
            # Reverse iteration order for forward-looking DP
            if d == 0: ri, ci = range(n-1, -1, -1), range(m-1, -1, -1)
            elif d == 1: ri, ci = range(n), range(m)
            elif d == 2: ri, ci = range(n-1, -1, -1), range(m)
            else: ri, ci = range(n), range(m-1, -1, -1)

            for i in ri:
                for j in ci:
                    ni, nj = i + dr, j + dc
                    if grid[i][j] == 2:
                        sl2[d][i][j] = 1
                        if 0 <= ni < n and 0 <= nj < m and sl0[d][ni][nj] > 0:
                            sl2[d][i][j] += sl0[d][ni][nj]
                    if grid[i][j] == 0:
                        sl0[d][i][j] = 1
                        if 0 <= ni < n and 0 <= nj < m and sl2[d][ni][nj] > 0:
                            sl0[d][i][j] += sl2[d][ni][nj]

        ans = 0
        for i in range(n):
            for j in range(m):
                # Check all valid turns
                for d1, d2 in turns:
                    L1 = dp[d1][i][j]
                    if L1 == 0: continue
                    # Determine expected value for the next cell in the second segment
                    phase = 2 if L1 % 2 == 1 else 0
                    ni, nj = i + dirs[d2][0], j + dirs[d2][1]
                    if 0 <= ni < n and 0 <= nj < m:
                        L2 = sl2[d2][ni][nj] if phase == 2 else sl0[d2][ni][nj]
                        ans = max(ans, L1 + L2)
                    else:
                        ans = max(ans, L1)
                # Also consider straight segments (at most one turn includes zero turns)
                for d in range(4):
                    ans = max(ans, dp[d][i][j])

        return ans

import bisect

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        first_star = p.find('*')
        second_star = p.find('*', first_star + 1)

        A = p[:first_star]
        B = p[first_star+1:second_star]
        C = p[second_star+1:]

        LA, LB, LC = len(A), len(B), len(C)

        def get_occurrences(text, pat):
            if not pat:
                return []
            res = []
            start = 0
            while True:
                idx = text.find(pat, start)
                if idx == -1:
                    break
                res.append(idx)
                start = idx + 1
            return res

        starts_A = get_occurrences(s, A)
        starts_B = get_occurrences(s, B)
        starts_C = get_occurrences(s, C)

        min_len = float('inf')

        # Pattern is "**"
        if not A and not B and not C:
            return 0

        # Case where B is empty: pattern reduces to A*C
        if not B:
            if not C:
                # Pattern is A*
                return LA if starts_A else -1
            elif not A:
                # Pattern is *C
                return LC if starts_C else -1
            else:
                # Pattern is A*C
                for k in starts_C:
                    # Find largest i in starts_A such that i + LA <= k
                    idx = bisect.bisect_right(starts_A, k - LA)
                    if idx > 0:
                        min_len = min(min_len, k - starts_A[idx-1])
        else:
            # B is not empty
            if not starts_B:
                return -1

            for j in starts_B:
                # Find latest valid A before or at start of B
                if not A:
                    i = j
                else:
                    idx_i = bisect.bisect_right(starts_A, j - LA)
                    if idx_i == 0:
                        continue
                    i = starts_A[idx_i - 1]

                # Find earliest valid C after or at end of B
                if not C:
                    k = j + LB
                else:
                    idx_k = bisect.bisect_left(starts_C, j + LB)
                    if idx_k == len(starts_C):
                        continue
                    k = starts_C[idx_k]

                current_len = k + LC - i
                if current_len < min_len:
                    min_len = current_len

        return min_len if min_len != float('inf') else -1

class Solution:
    def countSubstrings(self, s: str) -> int:
        # cnt[d][r] stores the number of substrings ending at the previous position
        # that have remainder r when divided by d.
        cnt = [[0] * d for d in range(10)]
        ans = 0

        for c in s:
            c_val = int(c)
            # Update remainder counts for all possible divisors d in 1..9
            for d in range(1, 10):
                new_cnt = [0] * d
                # Shift existing remainders: (r * 10 + c_val) % d
                for r in range(d):
                    if cnt[d][r]:
                        nr = (r * 10 + c_val) % d
                        new_cnt[nr] += cnt[d][r]
                # Add the new substring starting and ending at the current position
                new_cnt[c_val % d] += 1
                cnt[d] = new_cnt

            # If the current digit is non-zero, add valid substrings ending here
            if c_val > 0:
                ans += cnt[c_val][0]

        return ans

class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        low, high = 0, m * max(points)
        ans = 0
        while low <= high:
            mid = (low + high) // 2
            cost = 0
            for p in points:
                cost += (mid + p - 1) // p
                if cost > m:
                    break
            if cost <= m:
                ans = mid
                low = mid + 1
            else:
                high = mid - 1
        return ans

