class Solution:
    def minimumIncrements(self, nums: List[int], target: List[int]) -> int:
        k = len(target)
        # Precompute LCM for each subset mask of target
        lcm_map = {}
        for mask in range(1, 1 << k):
            l = 1
            for i in range(k):
                if (mask >> i) & 1:
                    l = math.lcm(l, target[i])
            lcm_map[mask] = l

        # For each mask, find the top 4 cheapest (cost, index) pairs from nums
        candidates = {}
        for mask, l in lcm_map.items():
            costs = [((l - (n % l)) % l, idx) for idx, n in enumerate(nums)]
            candidates[mask] = heapq.nsmallest(4, costs)

        # Generate all set partitions of target indices
        def get_partitions(elements):
            if not elements:
                return [[]]
            first = elements[0]
            rest = elements[1:]
            partitions = get_partitions(rest)
            result = []
            for p in partitions:
                for i in range(len(p)):
                    new_p = [s.copy() for s in p]
                    new_p[i].add(first)
                    result.append(new_p)
                result.append([s.copy() for s in p] + [{first}])
            return result

        all_partitions = get_partitions(list(range(k)))
        min_ops = float('inf')

        # For each partition, try all combinations of top candidates
        for part in all_partitions:
            masks = []
            for s in part:
                m = 0
                for i in s:
                    m |= (1 << i)
                masks.append(m)

            # product generates all combinations of candidates for each subset in the partition
            for combo in product(*[candidates[m] for m in masks]):
                indices = [c[1] for c in combo]
                # Ensure distinct elements from nums are used
                if len(set(indices)) == len(indices):
                    total_cost = sum(c[0] for c in combo)
                    if total_cost < min_ops:
                        min_ops = total_cost

        return min_ops

class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        def count_pairs(A, B, k):
            M = k - 1
            if M < 0:
                return 0
            X_end = min(A - 1, M)
            if X_end < 0:
                return 0
            x1 = M - B + 1
            if x1 < 0:
                return (X_end + 1) * (M + 1) - X_end * (X_end + 1) // 2
            elif x1 >= X_end:
                return B * (X_end + 1)
            else:
                part1 = B * (x1 + 1)
                num_terms = X_end - x1
                first_term = B - 1
                last_term = M + 1 - X_end
                part2 = (first_term + last_term) * num_terms // 2
                return part1 + part2

        def calc_max_sum(arr, k):
            n = len(arr)
            L = [-1] * n
            stack = []
            for i in range(n):
                while stack and arr[stack[-1]] < arr[i]:
                    stack.pop()
                if stack:
                    L[i] = stack[-1]
                stack.append(i)

            R = [n] * n
            stack = []
            for i in range(n - 1, -1, -1):
                while stack and arr[stack[-1]] <= arr[i]:
                    stack.pop()
                if stack:
                    R[i] = stack[-1]
                stack.append(i)

            total = 0
            for i in range(n):
                A = i - L[i]
                B = R[i] - i
                cnt = count_pairs(A, B, k)
                total += arr[i] * cnt
            return total

        return calc_max_sum(nums, k) - calc_max_sum([-x for x in nums], k)

