def mat_mul(A, B, p, N):
    C = [[0] * N for _ in range(N)]
    for i in range(N):
        for k in range(N):
            if A[i][k] == 0:
                continue
            val = A[i][k]
            row_b = B[k]
            row_c = C[i]
            for j in range(N):
                row_c[j] += val * row_b[j]
        for j in range(N):
            C[i][j] %= p
    return C

def mat_pow(A, exp, p, N):
    res = [[0] * N for _ in range(N)]
    for i in range(N):
        res[i][i] = 1
    base = [row[:] for row in A]
    while exp > 0:
        if exp % 2 == 1:
            res = mat_mul(res, base, p, N)
        base = mat_mul(base, base, p, N)
        exp //= 2
    return res

