class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)
        blocks = []
        curr = 1
        for i in range(1, n):
            if s[i] == s[i-1]:
                curr += 1
            else:
                blocks.append(curr)
                curr = 1
        blocks.append(curr)

        def check(L):
            flips = 0
            for b in blocks:
                flips += b // (L + 1)
                if flips > numOps:
                    return False
            return True

        low, high = 1, n
        ans = n
        while low <= high:
            mid = (low + high) // 2
            if check(mid):
                ans = mid
                high = mid - 1
            else:
                low = mid + 1
        return ans

