            x //= 2
        sum_f_A += x

    max_A = max(A)
    max_val = 2 * max_A
    k = 1
    while (1 << k) <= max_val:
        M = 1 << k
        cnt = {}
        sm = {}
        for x in A:
            r = x % M
            if r in cnt:
                cnt[r] += 1
                sm[r] += x
            else:
                cnt[r] = 1
                sm[r] = x

        H_k = 0
        for r, c in cnt.items():
            r2 = (M - r) % M
            if r2 in sm:
                H_k += c * sm[r2] + sm[r] * cnt[r2]

        S -= H_k // M
        k += 1

    ans = (S + sum_f_A) // 2
