class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        parent = list(range(threshold + 1))

        def find(i):
            while parent[i] != i:
                parent[i] = parent[parent[i]]
                i = parent[i]
            return i

        def union(i, j):
            root_i = find(i)
            root_j = find(j)
            if root_i != root_j:
                parent[root_i] = root_j

        last_seen = [0] * (threshold + 1)

        for num in nums:
            if num > threshold:
                continue
            for m in range(num, threshold + 1, num):
                if last_seen[m]:
                    union(num, last_seen[m])
                last_seen[m] = num

        isolated = sum(1 for x in nums if x > threshold)

        components = 0
        for num in nums:
            if num <= threshold and find(num) == num:
                components += 1

        return components + isolated
